effect.frag.content:
uniform float u_amount;
const float TAU = 6.28318530718;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
void main() {
  float wave = sin(v_uv.y * 70.0 - u_progress * TAU) * u_amount * 0.035;
  vec4 c = sourceAt(v_uv + vec2(wave, 0.0));
  vec4 r = sourceAt(v_uv + vec2(wave * 1.8, 0.0));
  c.r = min(c.a, r.a > 0.0 ? r.r / r.a * c.a : 0.0);
  fragColor = c;
}
